import threading
import time


class TokenBucket:
    def __init__(self, capacity: int, refill_per_s: float) -> None:
        self.capacity = capacity
        self.refill_per_s = refill_per_s
        self.tokens = float(capacity)
        self.last = time.monotonic()

    def take(self) -> bool:
        now = time.monotonic()
        self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.refill_per_s)
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False


class RateLimiter:
    def __init__(self, capacity: int, refill_per_s: float) -> None:
        self._buckets: dict[str, TokenBucket] = {}
        self._lock = threading.Lock()
        self._capacity = capacity
        self._refill = refill_per_s

    def allow(self, key: str) -> bool:
        with self._lock:
            bucket = self._buckets.setdefault(key, TokenBucket(self._capacity, self._refill))
        return bucket.take()

